export function PageComponent({
  route = "{{route}}",
  siteName = "{{siteName}}",
  accent = "{{accent}}",
  showChrome = {{showChrome}},
}) {
  const bodies = { home: "Home feed", settings: "Settings form", profile: "Profile card" };
  return (
    <div style={{ font: "12px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", borderRadius: 12, width: 300, boxSizing: "border-box", overflow: "hidden", border: "1.5px solid #24143020" }}>
      {showChrome && (
        <div style={{ display: "flex", alignItems: "center", gap: 5, padding: "8px 10px", background: "#24143010" }}>
          <span style={{ width: 7, height: 7, borderRadius: "50%", background: "#24143030", display: "block" }} />
          <span style={{ width: 7, height: 7, borderRadius: "50%", background: "#24143030", display: "block" }} />
          <span style={{ width: 7, height: 7, borderRadius: "50%", background: "#24143030", display: "block" }} />
          <span style={{ marginLeft: 8, fontSize: 10, color: "#24143099", background: "#ffffff", padding: "2px 8px", borderRadius: 4 }}>{siteName}.app/{route}</span>
        </div>
      )}
      <div style={{ padding: 12, fontWeight: 700, background: accent }}>{siteName}</div>
      <div style={{ padding: "24px 12px", textAlign: "center", color: "#24143099" }}>{bodies[route]}</div>
    </div>
  );
}
